    private static void Assert(bool value,string text){if(!value)throw new Exception(text);}
    private static object Normal(object value){return Json.Read<object>(Json.Write(value));}
    private static string Value(object value,string key){return Json.Str(Json.Get(value,key));}
    private static void Reject(int status,Action action){try{action();}catch(WebhookException error){Assert(error.StatusCode==status,"Expected "+status+", got "+error.StatusCode);return;}throw new Exception("Expected enrollment rejection "+status);}
    private static string Enc(object value){return Convert.ToBase64String(Encoding.UTF8.GetBytes(Json.Write(value))).TrimEnd('=').Replace('+','-').Replace('/','_');}
    private static string Digest(string path){using(var hash=SHA256.Create())return Convert.ToBase64String(hash.ComputeHash(File.ReadAllBytes(path)));}
    private const string BrowserState="fictional_browser_state_012345678901234567890";
    private static string BrowserUrl(int port=1455){return "https://auth.openai.com/oauth/authorize?response_type=code&client_id=app_EMoamEEZ73f0CkXaXp7hrann&redirect_uri="+Uri.EscapeDataString("http://127.0.0.1:"+port+"/auth/callback")+"&code_challenge="+new string('a',43)+"&code_challenge_method=S256&state="+BrowserState+"&scope=openid%20profile%20email%20offline_access%20api.connectors.read%20api.connectors.invoke";}
    private static string BrowserCallbackUrl(int port=1455){return "http://127.0.0.1:"+port+"/auth/callback?code=fictional-authorization-code&state="+BrowserState+"&scope=openid+profile";}
    private static void Invalid(Action action){try{action();}catch(InvalidOperationException){return;}throw new Exception("Expected safe browser contract rejection");}
    private sealed class Lease : IDisposable{private Action release;internal Lease(Action release){this.release=release;}public void Dispose(){var action=Interlocked.Exchange(ref release,null);if(action!=null)action();}}
    private static string Access(string account,int seconds=3600)
    {return "e30."+Enc(new Dictionary<string,object>{{"exp",DateTimeOffset.UtcNow.ToUnixTimeSeconds()+seconds},{"https://api.openai.com/auth",new{chatgpt_account_id=account,chatgpt_user_id="fictional-user"}}})+".fixture";}
    private static string Auth(string account="new-fixture",string email="new@example.invalid",string access=null,int? identitySeconds=3600)
    {var claims=new Dictionary<string,object>{{"sub","fictional-user"},{"email",email},{"https://api.openai.com/auth",new{chatgpt_account_id=account,chatgpt_plan_type="plus"}}};if(identitySeconds.HasValue)claims["exp"]=DateTimeOffset.UtcNow.ToUnixTimeSeconds()+identitySeconds.Value;return Json.Write(new{auth_mode="chatgpt",tokens=new{access_token=access??Access(account),refresh_token="fictional-refresh-never-network",account_id=account,id_token="e30."+Enc(claims)+".fixture"}});}
