        private readonly TaskCompletionSource<object> completion=new TaskCompletionSource<object>();private bool done;
        internal TaskCompletionSource<object> CancelBarrier=null;
        public int ProcessId{get{return 0;}}public long ProcessStartedTicks{get{return 0;}}
        internal Login(string home){Home=home;}
        public Task Initialize(CancellationToken token){return Task.FromResult(0);}
        public Task<object> Start(string loginMethod,CancellationToken token){LastMethod=loginMethod;Starts++;Directory.CreateDirectory(Path.Combine(Home,"tmp"));File.WriteAllText(Path.Combine(Home,"tmp","native-cache"),"fictional regenerable cache");Directory.CreateDirectory(Path.Combine(Home,"skills",".system"));File.WriteAllText(Path.Combine(Home,"skills",".system",".codex-system-skills.marker"),"fictional-native-marker");File.WriteAllText(Path.Combine(Home,"skills",".system","SKILL.md"),"fictional generated bundled source");return Task.FromResult(loginMethod=="browser"?Normal(new{type="chatgpt",loginId=Id,authUrl=AuthUrl}):Normal(new{type="chatgptDeviceCode",loginId=Id,verificationUrl="https://auth.openai.com/codex/device",userCode="ABCD-1234"}));}
        public Task<object> Read(CancellationToken token){Reads++;var identity=AuthIdentity.Parse(Authentication);return Task.FromResult(done?Normal(new{account=new{type="chatgpt",id=WrongAccount?"foreign-fixture":identity.AccountId,email=identity.Email}}):Normal(new{account=(object)null}));}
        public async Task<object> Completed(string id,CancellationToken token){using(token.Register(()=>completion.TrySetCanceled()))return await completion.Task.ConfigureAwait(false);}
        public async Task Cancel(string loginId,CancellationToken token){Assert(loginId==Id,"Cancelled a different native login");Interlocked.Increment(ref Cancels);if(CancelBarrier!=null)await CancelBarrier.Task.ConfigureAwait(false);}
        public void Dispose(){Interlocked.Increment(ref Disposals);}
        internal void Complete(){SafeFiles.AtomicWrite(Path.Combine(Home,"auth.json"),Encoding.UTF8.GetBytes(Authentication));done=true;completion.TrySetResult(Normal(new{loginId=WrongCompletedId?Guid.NewGuid().ToString("D"):Id,success=true}));}
    }
