            foreach(string name in new[]{".sqlite-maintenance.lock",".other-maintenance.lock"})using(var f=new Fixture(sandbox))using(var waiting=new ManualResetEventSlim()){string id=Value(f.Start(),"id");f.Wait(id,"awaiting-authorization");string home=f.Logins[0].Home,evidence=Path.Combine(home,name),cache=Path.Combine(home,"tmp","native-cache");File.WriteAllBytes(evidence,new byte[0]);f.Dependencies.CleanupWaiting=()=>waiting.Set();using(VaultMutation.Acquire(f.Root,CancellationToken.None)){f.Service.Cancel(f.Route.Id,f.Actor,id);Assert(waiting.Wait(5000),"Cleanup did not reach the mutation lease barrier");if(name==".sqlite-maintenance.lock")File.WriteAllText(evidence,"fictional protected lock content added while waiting");}DateTime end=DateTime.UtcNow.AddSeconds(5);while(Value(f.Get(id),"cleanupState")!="retained"&&DateTime.UtcNow<end)Thread.Sleep(5);Assert(Value(f.Get(id),"cleanupState")=="retained"&&File.Exists(evidence)&&File.Exists(cache)&&Directory.Exists(home),"Cleanup removed changed or unknown lock content");if(name==".sqlite-maintenance.lock")Assert(File.ReadAllText(evidence)=="fictional protected lock content added while waiting","Changed native lock content was altered");}
        });
        check("enrollment cleanup preserves chat history user files changed config and mismatched ownership",()=>{
            foreach(string preserve in new[]{"history","workspace","config","manifest","tmp-notes","sandbox-history","nested-git","modified-system-skill"})using(var f=new Fixture(sandbox)){string id=Value(f.Start(),"id");f.Wait(id,"awaiting-authorization");string home=f.Logins[0].Home,folder=Path.GetDirectoryName(home),evidence;
                if(preserve=="history"){Directory.CreateDirectory(Path.Combine(home,"sessions"));evidence=Path.Combine(home,"sessions","fictional-history.jsonl");File.WriteAllText(evidence,"fictional protected transcript");}
                else if(preserve=="workspace"){evidence=Path.Combine(folder,"workspace","source.txt");File.WriteAllText(evidence,"fictional protected source");}
                else if(preserve=="config"){evidence=Path.Combine(home,"config.toml");File.AppendAllText(evidence,"# fictional user config change\n");}
                else if(preserve=="manifest"){evidence=Path.Combine(home,"installation_id");File.WriteAllText(evidence,"fictional installation");string manifest="portal-enrollment-home-"+Path.GetFileName(folder)+".dpapi";var owner=f.Store.ReadRecord<PortalEnrollmentHomeOwner>(manifest);owner.EnrollmentId=new string('e',32);f.Store.WriteRecord(manifest,owner);}
                else if(preserve=="tmp-notes"){evidence=Path.Combine(home,"tmp","notes.md");File.WriteAllText(evidence,"fictional user notes");}
                else if(preserve=="sandbox-history"){Directory.CreateDirectory(Path.Combine(home,".sandbox"));evidence=Path.Combine(home,".sandbox","history.jsonl");File.WriteAllText(evidence,"fictional protected history");}
                else if(preserve=="nested-git"){Directory.CreateDirectory(Path.Combine(home,"tmp",".git"));evidence=Path.Combine(home,"tmp",".git","index");File.WriteAllText(evidence,"fictional protected git index");}
                else{evidence=Path.Combine(home,"skills",".system","SKILL.md");File.AppendAllText(evidence,"\nfictional user source change");}
                f.Service.Cancel(f.Route.Id,f.Actor,id);DateTime end=DateTime.UtcNow.AddSeconds(5);while(Value(f.Get(id),"cleanupState")!="retained"&&DateTime.UtcNow<end)Thread.Sleep(5);Assert(File.Exists(evidence)&&Directory.Exists(home)&&Value(f.Get(id),"cleanupWarning").Length>0,"Cleanup removed protected "+preserve);
            }
        });
        check("enrollment cleanup rechecks files added while waiting for the account mutation lease",()=>{
            using(var f=new Fixture(sandbox))using(var waiting=new ManualResetEventSlim()){string id=Value(f.Start(),"id");f.Wait(id,"awaiting-authorization");string notes=Path.Combine(f.Logins[0].Home,"tmp","notes.md");f.Dependencies.CleanupWaiting=()=>waiting.Set();using(VaultMutation.Acquire(f.Root,CancellationToken.None)){f.Service.Cancel(f.Route.Id,f.Actor,id);Assert(waiting.Wait(5000),"Cleanup did not reach the mutation lease barrier");File.WriteAllText(notes,"fictional protected note added during lease wait");}DateTime end=DateTime.UtcNow.AddSeconds(5);while(Value(f.Get(id),"cleanupState")!="retained"&&DateTime.UtcNow<end)Thread.Sleep(5);Assert(File.Exists(notes)&&Value(f.Get(id),"cleanupWarning").Length>0,"Lease wait hid new user content from cleanup");}
        });
        check("enrollment active admission index cannot be hidden by hundreds of historical receipts",()=>{
            using(var f=new Fixture(sandbox)){for(int i=0;i<260;i++)f.Store.WriteRecord("portal-enrollment-old-"+i+".dpapi",new PortalEnrollmentRecord{Id=Guid.NewGuid().ToString("N"),State="cancelled"});string id=Value(f.Start(),"id");f.Wait(id,"awaiting-authorization");Reject(409,()=>f.Start("second"));Assert(f.Logins.Count==1&&RelayEngine.Rows(Json.Get(Normal(f.Service.Capabilities(f.Route.Id,f.Actor)),"active")).Count()==1,"Historical receipts hid a live admission");}
        });
        check("enrollment cancellation waits for a delayed login factory before cleaning its reserved home",()=>{
            using(var f=new Fixture(sandbox))using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim()){
                f.Dependencies.Login=(binary,root,home)=>{entered.Set();if(!release.Wait(5000))throw new Exception("Fictional factory timeout");Directory.CreateDirectory(home);var login=new Login(home);lock(f.Logins)f.Logins.Add(login);return login;};
                string id=Value(f.Start(),"id");Assert(entered.Wait(5000),"Login factory never started");string homePath=InstancePaths.Home(f.Root,f.Record(id).InstanceId);f.Service.Cancel(f.Route.Id,f.Actor,id);Assert(Directory.Exists(homePath),"Cleanup ran before the in-flight constructor returned");release.Set();DateTime end=DateTime.UtcNow.AddSeconds(5);while(Value(f.Get(id),"cleanupState")!="complete"&&DateTime.UtcNow<end)Thread.Sleep(5);Assert(f.Logins.Count==1&&f.Logins[0].Disposals==1&&!Directory.Exists(Path.GetDirectoryName(homePath)),"Delayed constructor recreated an orphan after cleanup");
            }
        });
        check("enrollment signed HTTP browser callback contract binds the owner and never persists return URL or native state",()=>{
            using(var f=new Fixture(sandbox)){var policy=PortalAdministration.Save(f.Store,new PortalAdministrationPolicy{Enabled=true,RootRouteId=f.Route.Id,SiteOrigin="https://portal.example.com",AllowedEmails=new List<string>{"owner@example.com"}});
                Func<string,string,string,WebhookHttpRequest> request=(suffix,method,body)=>{var value=new WebhookHttpRequest{Method=method,Path="/v1/admin/"+f.Route.Id+"/"+suffix,Body=body};value.Headers["Authorization"]="Switcher-Admin v1";value.Headers["X-Switcher-Admin-Site"]=policy.SiteOrigin;value.Headers["X-Switcher-Admin-Route"]=f.Route.Id;value.Headers["X-Switcher-Admin-User"]="user_owner";value.Headers["X-Switcher-Admin-Email"]="owner@example.com";value.Headers["X-Switcher-Admin-Time"]=DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString();value.Headers["X-Switcher-Admin-Nonce"]=Guid.NewGuid().ToString("N");value.Headers["X-Switcher-Admin-Body"]=Webhooks.Hash(body);if(method=="POST")value.Headers["Idempotency-Key"]="http-browser";value.Headers["X-Switcher-Admin-Signature"]=PortalAdministration.Sign(value,policy.Secret);return value;};
                var invalid=PortalAdministrationHttp.Handle(f.Store,request("instance-enrollments","POST",Json.Write(new{name="Fictional browser HTTP instance",exposeInPortal=true,loginMethod="unsupported"})),f.Service);Assert(invalid.Status==400,"HTTP accepted unsupported login method");
                var start=PortalAdministrationHttp.Handle(f.Store,request("instance-enrollments","POST",Json.Write(new{name="Fictional browser HTTP instance",exposeInPortal=true,loginMethod="browser"})),f.Service);Assert(start.Status==202,"HTTP rejected browser login method");string id=Value(Json.Read<object>(start.Body),"id");f.Wait(id,"awaiting-authorization");string path="instance-enrollments/"+id+"/browser-callback";
                Assert(PortalAdministrationHttp.Handle(f.Store,request(path,"GET",""),f.Service).Status==405,"HTTP GET could submit an OAuth callback");Assert(PortalAdministrationHttp.Handle(f.Store,request(path,"POST","{\"callbackUrl\":\"one\",\"callbackUrl\":\"two\"}"),f.Service).Status==400,"HTTP accepted duplicate callbackUrl");
                var unsigned=request(path,"POST",Json.Write(new{callbackUrl=BrowserCallbackUrl()}));unsigned.Headers["X-Switcher-Admin-Signature"]=new string('0',64);Assert(PortalAdministrationHttp.Handle(f.Store,unsigned,f.Service).Status==403&&f.BrowserTargets.Count==0,"Unsigned callback reached native login");Reject(404,()=>f.Service.BrowserCallback(f.Route.Id,f.OtherActor,id,BrowserCallbackUrl()));
                Assert(PortalAdministrationHttp.Handle(f.Store,request(path,"POST",Json.Write(new{callbackUrl=BrowserCallbackUrl()})),f.Service).Status==202,"Signed callback rejected its native return");f.Wait(id,"identity-confirmation",20);Assert(PortalAdministrationHttp.Handle(f.Store,request(path,"POST",Json.Write(new{callbackUrl=BrowserCallbackUrl()})),f.Service).Status==202&&f.BrowserTargets.Count==2,"HTTP callback retry replayed native authorization");string receipt=Json.Write(f.Record(id));Assert(!receipt.Contains(BrowserState)&&!receipt.Contains("fictional-authorization-code")&&!receipt.Contains("oauth/authorize"),"Signed browser callback became durable");
            }
        });
        check("enrollment HTTP start get confirm preserves exact 64 hex identity and 32 hex operation contract",()=>{
            using(var f=new Fixture(sandbox)){f.Known();var policy=PortalAdministration.Save(f.Store,new PortalAdministrationPolicy{Enabled=true,RootRouteId=f.Route.Id,SiteOrigin="https://portal.example.com",AllowedEmails=new List<string>{"owner@example.com"}});
                Func<string,string,string,WebhookHttpRequest> request=(suffix,method,body)=>{var value=new WebhookHttpRequest{Method=method,Path="/v1/admin/"+f.Route.Id+"/"+suffix,Body=body};value.Headers["Authorization"]="Switcher-Admin v1";value.Headers["X-Switcher-Admin-Site"]=policy.SiteOrigin;value.Headers["X-Switcher-Admin-Route"]=f.Route.Id;value.Headers["X-Switcher-Admin-User"]="user_owner";value.Headers["X-Switcher-Admin-Email"]="owner@example.com";value.Headers["X-Switcher-Admin-Time"]=DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString();value.Headers["X-Switcher-Admin-Nonce"]=Guid.NewGuid().ToString("N");value.Headers["X-Switcher-Admin-Body"]=Webhooks.Hash(body);if(method=="POST")value.Headers["Idempotency-Key"]="http-once";value.Headers["X-Switcher-Admin-Signature"]=PortalAdministration.Sign(value,policy.Secret);return value;};
                var start=PortalAdministrationHttp.Handle(f.Store,request("instance-enrollments","POST",Json.Write(new{name="Fictional HTTP instance",accountId=f.KnownId(),exposeInPortal=true})),f.Service);Assert(start.Status==202,"HTTP rejected opaque known-account id");var view=Json.Read<object>(start.Body);string id=Value(view,"id"),hash=Value(Json.Get(view,"identity"),"hash");Assert(id.Length==32&&hash.Length==64,"HTTP contract ID shape mismatch");Assert(PortalAdministrationHttp.Handle(f.Store,request("instance-enrollments/"+id,"GET",""),f.Service).Status==200,"HTTP Get not owner bound");Assert(PortalAdministrationHttp.Handle(f.Store,request("instance-enrollments/"+id+"/confirm","POST",Json.Write(new{identityHash=hash})),f.Service).Status==202,"HTTP confirmation rejected returned identity hash");f.Wait(id,"ready");Assert(PortalAdministrationHttp.Handle(f.Store,request("instance-enrollments/"+id+"/confirm","POST",Json.Write(new{identityHash=hash})),f.Service).Status==202,"HTTP confirmation retry duplicated or failed");
            }
        });
